{
  "slots": {
    "question": [
      {
        "claim": "The paper asks whether online political hostility is associated with political engagement and its antecedents, beyond explanations based on socioeconomic marginalization, personality traits, or grievance.",
        "quotes": [
          "We extend this revisionist perspective to online political hostility by asking whether hostile political expression on X/Twitter is associated not only with deprivation or personality-based explanations, but also with political engagement and its antecedents."
        ]
      }
    ],
    "central_claim": [
      "Online political hostility is positively associated with indicators of political engagement and its antecedents, including education, internal efficacy, political interest, political knowledge, and participation, with the strongest associations observed for political interest, political knowledge, and online/offline participation.",
      "Politically engaged users who express hostility also post more frequently, have more friends and followers, and thus have greater potential reach on X/Twitter, suggesting that hostile expression is linked to higher visibility and activity."
    ],
    "evidence": [
      "The study combines two years of survey and behavioral data from American X/Twitter users, using a word embedding approach called the Super-Unsupervised (SU) method to measure online political hostility based on linguistic proximity to political and hostile language.",
      "The SU method is validated through face validity, convergent and discriminant validity, criterion validity, external validity, and ecological validity, including a test with expert raters showing 74% accuracy in identifying political hostility.",
      "The study uses a panel survey to measure political engagement indicators such as education, internal efficacy, political interest, political knowledge, and participation, and links these to behavioral data on X/Twitter activity.",
      "Affective polarization is measured through feeling thermometer ratings of political leaders (e.g., Trump, Biden, Cruz, Sanders), and the study examines whether the association between engagement and hostility is stronger among users with higher levels of affective polarization.",
      "The analysis employs cross-sectional and panel models, including Random-Intercept Cross-Lagged Panel Models (RI-CLPM), to assess temporal within-person associations between political engagement and hostility."
    ],
    "key_findings": [
      {
        "claim": "Online political hostility is positively and significantly associated with political interest, political knowledge, and online/offline participation.",
        "quotes": [
          "The associations were obtained after controlling for broad personality traits, income, age, gender, and party identification. The largest associations are generally observed for the primary measure of political hostility rather than for the more general AFINN or Perspective API measures."
        ]
      },
      {
        "claim": "Users with higher levels of affective polarization show stronger associations between political engagement and online political hostility, particularly for participatory indicators like online and offline participation.",
        "quotes": [
          "For those high on affective polarization fourteen out of eighteen associations, across our three measures of online hostility, are significant, whereas for those low on affective polarization only four out of eighteen are significant."
        ]
      },
      {
        "claim": "Politically hostile users post more frequently and have more followers and friends, indicating greater activity and potential reach on X/Twitter.",
        "quotes": [
          "A change from the mean level of hostility to 1.5 standard deviations above the mean is associated with an increase in the number of posts from around 420 to around 900 and an increase in the number of followers from around 220 to around 370."
        ]
      },
      {
        "claim": "The association between political engagement and online political hostility is stronger for more proximate indicators (e.g., political interest and knowledge) than for distal antecedents (e.g., education and internal efficacy).",
        "quotes": [
          "The associations with online participation and political interest are, for example, 0.236 (95% CI [0.186; 0.285]) and 0.306 (95% CI [0.247; 0.366]) for online political hostility, whereas they are 0.176 (95% CI [0.103; 0.249]) and 0.170 (95% CI [0.086; 0.253]) for AFINN scores and 0.267 (95% CI [0.212; 0.322]) and 0.239 (95% CI [0.170; 0.308]) for Perspective API scores."
        ]
      },
      {
        "claim": "The study finds that politically engaged users who express hostility are not limited to fringe audiences; they are more active and have greater potential reach, suggesting that hostile content is amplified by user activity.",
        "quotes": [
          "The greater engagement of hostile social media users may thus provide them with a higher reach than other users."
        ]
      }
    ],
    "scope_and_limits": [
      "The findings are observational and do not establish causality; time-varying confounding, reciprocal relationships, and measurement error may explain the observed associations.",
      "The study does not establish that political engagement causes hostility, and the results should be interpreted as associational rather than causal.",
      "The measure of affective polarization focuses on feelings toward political leaders rather than toward parties or party supporters, so the moderation results are limited to leader-directed affective polarization.",
      "The study does not provide evidence on the exact causal relationships between different indicators of political engagement and their antecedents, and the findings should not be interpreted as suggesting that, for example, more educated users are inherently more hostile.",
      "The primary measure of political hostility, while validated, may partly capture proximity to politically salient conflict language rather than hostility alone, and the study acknowledges this construct-validity limitation."
    ],
    "theoretical_positioning": [
      {
        "claim": "The paper situates its analysis within classical theories of political engagement and recent work on the darker sides of political engagement, extending and integrating the revisionist view that political engagement can lead to biased and antagonistic behavior.",
        "quotes": [
          "Building on classical theories of political engagement [17,19] and recent work on the darker sides of engagement, we find that online political hostility is positively associated with several indicators of political engagement and its antecedents."
        ]
      }
    ],
    "interlocutor_claim": [
      {
        "claim": "The paper disputes the claim that online political hostility is primarily driven by socioeconomic marginalization, status threat, or personality-based traits (such as the Dark Triad), by arguing that it is also strongly associated with political engagement and its antecedents.",
        "quotes": [
          "We extend this revisionist perspective to online political hostility by asking whether hostile political expression on X/Twitter is associated not only with deprivation or personality-based explanations, but also with political engagement and its antecedents."
        ]
      }
    ]
  }
}
